files.infra/nginx/nginx.conf:
upstream auth { server auth:8000; }
upstream users { server users:8000; }
upstream notifications { server notifications:8000; }

server {
    listen 80;

    location /api/auth/ { proxy_pass http://auth/; }
    location /api/users/ { proxy_pass http://users/; }
    location /api/notifications/ { proxy_pass http://notifications/; }

    location /health {
        access_log off;
        return 200 '{"status":"ok"}';
        add_header Content-Type application/json;
    }
}
